import re

def base36_encode(n):
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    result = ''
    for _ in range(4):
        result = chars[n % 36] + result
        n //= 36
    return result

def base36_decode(s):
    return int(s, 36)

def next_order_id():
    ids = []
    with open('ids.txt', 'r') as f:
        for line in f:
            line = line.strip()
            # Skip empty lines
            if not line:
                continue
            # Try to extract ORD-XXXX pattern from the line
            m = re.search(r'ORD-([0-9A-Za-z]{4})', line)
            if m:
                ids.append(m.group(1))

    if not ids:
        # No IDs found, start from the beginning
        next_suffix = '0000'
    else:
        last_suffix = ids[-1]
        last_num = base36_decode(last_suffix)
        next_suffix = base36_encode(last_num + 1)

    return f'ORD-{next_suffix}'

if __name__ == '__main__':
    print(next_order_id())

