import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_encode(num: int) -> str:
    if num == 0:
        return '0'
    result = []
    while num > 0:
        result.append(BASE36[num % 36])
        num //= 36
    return ''.join(reversed(result))


def base36_decode(s: str) -> int:
    result = 0
    for ch in s:
        result = result * 36 + BASE36.index(ch.upper())
    return result


def main():
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('ORD-0000')
        return

    if not lines:
        print('ORD-0000')
        return

    last_line = lines[-1]
    suffix = last_line.split('-')[1]

    num = base36_decode(suffix)
    next_num = num + 1
    next_suffix = base36_encode(next_num).zfill(4)

    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

