#!/usr/bin/env python3
"""Read attendees.txt (UTF-8, one name per line) and write roster.txt (UTF-8)
with the same names sorted alphabetically."""


def main():
    with open("attendees.txt", encoding="utf-8") as f:
        names = [line.rstrip("\n") for line in f]

    # Remove any trailing empty strings that might come from a final newline
    if names and names[-1] == "":
        names.pop()

    names.sort()

    with open("roster.txt", "w", encoding="utf-8") as f:
        for name in names:
            f.write(name + "\n")


if __name__ == "__main__":
    main()

