"""Deduplicate events.jsonl by event_id, keeping the last occurrence of each."""

import json

seen = {}
with open("events.jsonl", encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        event = json.loads(line)
        seen[event["event_id"]] = event  # later occurrence overwrites earlier

with open("deduped.jsonl", "w", encoding="utf-8") as out:
    for event in seen.values():
        out.write(json.dumps(event) + "\n")

