#!/usr/bin/env python3
"""Generate manifest.json mapping release files to their SHA-256 hex digests."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_hex(path: Path) -> str:
    """Return the SHA-256 hex digest of the file at *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    if not RELEASE_DIR.is_dir():
        raise SystemExit(f"error: {RELEASE_DIR} is not a directory")

    manifest = {}
    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if fpath.is_file():
            rel = str(fpath.relative_to(REPO_ROOT))
            manifest[rel] = sha256_hex(fpath)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)

    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

