#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def sha256_digest(filepath: str) -> str:
    """Return the hexadecimal SHA-256 digest of the given file."""
    hasher = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(65536)  # 64 KiB buffer
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for root, _dirs, files in os.walk(RELEASE_DIR):
        for filename in sorted(files):
            full_path = os.path.join(root, filename)
            rel_path = os.path.relpath(full_path).replace(os.sep, "/")
            manifest[rel_path] = sha256_digest(full_path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_FILE} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

