#!/usr/bin/env python3
"""Count word occurrences in all .txt files under docs/."""

import os
import re
from collections import Counter

def main():
    word_counts = Counter()
    docs_dir = "docs"

    # Walk through all .txt files in docs/
    for root, dirs, files in os.walk(docs_dir):
        for filename in files:
            if not filename.endswith(".txt"):
                continue
            filepath = os.path.join(root, filename)
            with open(filepath, "r", encoding="utf-8") as f:
                for line in f:
                    for raw_word in line.split():
                        # Lowercase and strip punctuation .,;:!? from edges
                        word = raw_word.strip(".,;:!?").lower()
                        if word:
                            word_counts[word] += 1

    # Sort alphabetically and write counts.txt
    with open("counts.txt", "w", encoding="utf-8") as out:
        for word in sorted(word_counts):
            out.write(f"{word} {word_counts[word]}\n")

if __name__ == "__main__":
    main()

