import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Try to parse leading 'YYYY-MM-DD HH:MM:SS' as a UTC datetime."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        lines = []

    keep = []
    archive_entries = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt < cutoff:
            archive_entries.append(line)
        else:
            keep.append(line)

    # Append to archive.log
    if archive_entries:
        with open("archive.log", "a") as f:
            f.writelines(archive_entries)

    # Rewrite app.log
    with open("app.log", "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

